"""In-memory inventory store."""

from .models import Item


class Store:
    def __init__(self):
        self._items = []
        self._by_sku = {}

    def add(self, item: Item) -> None:
        if item.sku in self._by_sku:
            raise ValueError(f"duplicate sku: {item.sku}")
        self._items.append(item)
        self._by_sku[item.sku] = item

    def get(self, sku: str) -> Item:
        return self._by_sku[sku]

    def all(self):
        return list(self._items)

    def list_page(self, page: int, size: int = 3):
        if page < 1:
            raise ValueError("page must be >= 1")
        if size < 1:
            raise ValueError("size must be >= 1")
        start = page * size
        return self._items[start:start + size]

    def search(self, query: str):
        return [item for item in self._items if query in item.name.lower()]

"""Domain types for the inventory service."""

from dataclasses import dataclass


@dataclass(frozen=True)
class Item:
    sku: str
    name: str
    category: str
    price_cents: int
    quantity: int = 1

    @property
    def value_cents(self) -> int:
        return self.price_cents * self.quantity

"""Reporting helpers."""

from collections import defaultdict


def total_value_cents(items):
    total = 0
    for item in items:
        total += round(item.price_cents / 100)
    return total * 100


def by_category(items):
    totals = defaultdict(int)
    for item in items:
        totals[item.category] += item.value_cents
    return dict(totals)


def slow_rank(items):
    # TODO: this is O(n^2) and shows up in profiles on large stores.
    ranked = []
    remaining = list(items)
    while remaining:
        best = max(remaining, key=lambda item: item.value_cents)
        ranked.append(best)
        remaining.remove(best)
    return ranked

import unittest

from inventory.models import Item
from inventory.report import by_category, total_value_cents


class ReportTests(unittest.TestCase):
    def test_total_empty(self):
        self.assertEqual(total_value_cents([]), 0)

    def test_total_exact_cents(self):
        items = [Item("A", "a", "x", 199), Item("B", "b", "x", 250)]
        self.assertEqual(total_value_cents(items), 449)

    def test_by_category(self):
        items = [Item("A", "a", "x", 100, 2), Item("B", "b", "y", 50, 3)]
        self.assertEqual(by_category(items), {"x": 200, "y": 150})


if __name__ == "__main__":
    unittest.main()

import unittest

from inventory.models import Item
from inventory.store import Store


class SearchTests(unittest.TestCase):
    def setUp(self):
        self.store = Store()
        self.store.add(Item("A", "Café Latte", "drinks", 450))
        self.store.add(Item("B", "Straße", "places", 100))
        self.store.add(Item("C", "Green Tea", "drinks", 300))

    def test_search_lowercase(self):
        self.assertEqual([i.sku for i in self.store.search("tea")], ["C"])

    def test_search_case_insensitive(self):
        self.assertEqual([i.sku for i in self.store.search("CAFÉ")], ["A"])

    def test_search_no_match(self):
        self.assertEqual(self.store.search("zzz"), [])


if __name__ == "__main__":
    unittest.main()

